const identifyTaskDB=[{"s":"La estructura de cinco actos que sube a un clímax y cae, dibujada como una montaña.","type":"La pirámide (Freytag, 1863)"},{"s":"El vuelco de la acción hacia lo contrario de lo que se esperaba.","type":"La peripecia (Aristóteles)"},{"s":"El paso de la ignorancia al saber, dentro de la misma historia.","type":"El reconocimiento (Aristóteles)"},{"s":"Salida, iniciación y regreso: un solo viaje que se repetiría en los mitos del mundo.","type":"El monomito (Campbell, 1949)"},{"s":"La objeción de que el monomito no es un método folclórico comprobable.","type":"La crítica de Alan Dundes"},{"s":"El monomito adaptado, paso a paso, para el guion de cine comercial.","type":"El viaje del escritor (Vogler, 1992)"},{"s":"Planteamiento, confrontación y resolución, con giros en páginas fijas.","type":"El paradigma de tres actos (Field, 1979)"},{"s":"Quince golpes con su página aproximada, para vender un guion.","type":"Los quince golpes (Snyder, 2005)"},{"s":"Seis formas emocionales medidas en 1,327 obras, con su corpus escrito.","type":"Reagan, Mitchell, Kiley, Danforth y Dodds (2016)"},{"s":"Cuatro partes tradicionales cuyo tercer movimiento es un giro, no un choque.","type":"Kishōtenketsu"}];
const classifyTaskDB=[{"w":"La pirámide","gen":"Estructura","n":"Acción ascendente, clímax y caída","g":"Clásico del drama","t":"Freytag, 1863"},{"w":"El monomito","gen":"Estructura","n":"Salida, iniciación y regreso","g":"Plantilla influyente","t":"Campbell, 1949"},{"w":"Los quince golpes","gen":"Estructura","n":"Beats con página aproximada","g":"Plantilla de industria","t":"Snyder, 2005"},{"w":"Las seis formas medidas","gen":"Hallazgo","n":"Tono emocional agrupado en seis curvas","g":"Medición con corpus","t":"Reagan y colegas, 2016"},{"w":"Kishōtenketsu","gen":"Forma tradicional","n":"Cuatro partes; giro sin choque","g":"Sin autor único","t":"Asia oriental"},{"w":"La peripecia","gen":"Pieza","n":"El vuelco hacia lo contrario","g":"Poética de Aristóteles","t":"s. IV a. C."},{"w":"El reconocimiento","gen":"Pieza","n":"El paso de la ignorancia al saber","g":"Poética de Aristóteles","t":"s. IV a. C."},{"w":"La objeción de Dundes","gen":"Crítica","n":"El monomito no es método comprobable","g":"Folclore","t":"Sobre Campbell, 1949"},{"w":"La teoría de la bolsa","gen":"Crítica","n":"Cuestiona el modelo héroe-lanza-choque","g":"Le Guin, 1986","t":"No es medición"},{"w":"Meandro, espiral, red","gen":"Catálogo","n":"Patrones que no son un arco","g":"Alison, 2019","t":"No es medición"}];
const completeTaskDB=[{"s":"La pirámide es de Gustav ___.","opts":["Freytag","Campbell","Snyder"],"ans":"Freytag"},{"s":"El monomito lo propuso Joseph ___, en 1949.","opts":["Campbell","Propp","Todorov"],"ans":"Campbell"},{"s":"Alan ___ objetó que el monomito no es comprobable.","opts":["Dundes","Lévi-Strauss","Aristóteles"],"ans":"Dundes"},{"s":"Los quince golpes son de Blake ___, 2005.","opts":["Snyder","Field","Vogler"],"ans":"Snyder"},{"s":"Reagan y colegas midieron obras del Proyecto ___.","opts":["Gutenberg","Alejandría","Babel"],"ans":"Gutenberg"},{"s":"El ___ es una forma tradicional sin autor único.","opts":["kishōtenketsu","monomito","paradigma"],"ans":"kishōtenketsu"},{"s":"Ursula K. Le Guin propuso la teoría de la ___.","opts":["bolsa","lanza","pirámide"],"ans":"bolsa"},{"s":"Lo que no se puede comprobar se deja ___.","opts":["pendiente","inventado","oculto"],"ans":"pendiente"}];
const explainQuestions=[{"q":"Explica por qué ninguna estructura se puede citar sin su autor y su año, y qué pasa cuando se cita sin ellos.","ans":"Una estructura sin autor ni año no se puede evaluar: no se sabe de qué género salió, para qué formato se pensó ni qué tan vieja o nueva es la idea. Se vuelve una frase que suena a ley («así se cuentan las historias») y que nadie puede discutir porque no hay a quién preguntarle ni qué fecha comparar. Con el autor y el año, en cambio, la estructura se puede poner en su sitio: la pirámide de Freytag es de 1863 y describe el drama alemán de su época, así que aplicarla a un video de siete minutos es, como mínimo, una decisión que hay que justificar, no un hecho que se pueda dar por sentado."},{"q":"Explica la diferencia entre lo que hizo Propp (1928, visto en la etapa 2) y lo que hizo Campbell (1949) en esta etapa.","ans":"Propp tomó cien cuentos maravillosos rusos y contó, uno por uno, qué función cumplía cada parte: encontró 31 funciones que se repetían siempre en el mismo orden, y dijo que su hallazgo valía para ese género. Es un trabajo comprobable: cualquiera puede coger otros cien cuentos y ver si el esqueleto aparece, como hizo Alan Dundes con cuentos de indios norteamericanos en 1964. Campbell, en cambio, leyó mitos de muchas culturas buscando sentido, no contando funciones, y afirmó que su patrón (el monomito) valía para todos los mitos del mundo. El propio Dundes le objetó que eso no es un método folclórico comprobable, sino una lectura personal que se ajusta después recortando lo que no encaja."},{"q":"Explica qué es una plantilla de industria declarada, y por qué se puede usar aunque no sea un hallazgo.","ans":"Una plantilla de industria declarada es una fórmula de oficio, como el paradigma de tres actos de Syd Field (1979) o los quince golpes de Blake Snyder (2005), pensada para vender un guion de cine comercial y presentada por su propio autor como eso: un manual práctico, no un descubrimiento sobre la narración humana. Se puede usar porque, dentro de su propósito (escribir un guion vendible), funciona; lo que no se puede hacer es venderla como si fuera ciencia o como si describiera cómo funcionan todas las historias. La diferencia entre usarla bien y usarla mal no está en usarla, está en decir de dónde sale."},{"q":"Explica qué midieron Reagan, Mitchell, Kiley, Danforth y Dodds en 2016 y cuál es el límite que el propio estudio reconoce.","ans":"En 2016, ese equipo publicó en EPJ Data Science un estudio que midió el tono emocional, palabra por palabra, de 1,327 obras de ficción del Proyecto Gutenberg, usando un diccionario de palabras ya puntuadas por su carga emocional. Con herramientas estadísticas de reducción de dimensiones, agruparon las curvas resultantes en seis formas que se repetían con fuerza estadística real. Es la medición más seria que existe hoy sobre el tema, y aun así el propio estudio reconoce por escrito su límite: ese corpus de 1,327 obras es, en su enorme mayoría, occidental y está en inglés, así que las seis formas describen ese conjunto de libros, no necesariamente la narración humana entera."},{"q":"Explica por qué el kishōtenketsu, la bolsa de Le Guin y la espiral de Alison no son un defecto de las historias que las usan.","ans":"Estas tres formas no tienen arco de tensión (una subida y una bajada con un choque en el medio), y por eso alguien acostumbrado solo a la pirámide o al monomito podría pensar que les falta algo. Pero el kishōtenketsu resuelve su tercer movimiento con un giro, un cambio de perspectiva, no con un choque, y no necesita antagonista para funcionar; Ursula K. Le Guin, en «The Carrier Bag Theory of Fiction» (1986), propuso que hay historias que reúnen en vez de enfrentar, como quien llena una bolsa; y Jane Alison, en «Meander, Spiral, Explode» (2019), catalogó patrones reales que serpentean o vuelven sobre sí mismos en vez de subir a un clímax. Ninguna de las tres es una historia incompleta: son formas distintas, tan legítimas como el arco, que el modelo héroe-lanza-choque simplemente no incluye."},{"q":"Explica qué se hace cuando el autor, la fecha o la cifra de una estructura no se pueden comprobar.","ans":"El quinto movimiento del protocolo de esta etapa dice que, si algo no se puede verificar, se deja pendiente, a la vista, en vez de inventarlo. Eso significa escribir, por ejemplo, «autor: no se pudo comprobar» en lugar de atribuirle la estructura a un nombre conocido solo para que la cita suene completa. Una casilla vacía con esa nota es un dato honesto: dice que la casa buscó y no encontró, y deja la puerta abierta para que alguien más lo compruebe después. Inventar el dato que falta, en cambio, convierte una estructura huérfana en una mentira con apariencia de cita, que es justo lo que la regla de oro de esta materia prohíbe."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la estructura ilustrada en cada oración. Escribe al lado de qué estructura se trata.','<strong>Ejemplo:</strong> Cuatro partes tradicionales cuyo tercer movimiento es un giro, no un choque. → <span style="color:var(--jade);font-weight:700;">Kishōtenketsu</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

