const evalTFBank=[{"q":"La regla de oro de esta materia exige que toda estructura se cite con autor, año y crítica.","a":true},{"q":"Aristóteles pide que una historia tenga principio, medio y fin, y que en el medio pueda haber peripecia y reconocimiento.","a":true},{"q":"La pirámide de Freytag es una ley universal de toda narración.","a":false},{"q":"Freytag publicó su pirámide en 1863, describiendo el drama alemán de cinco actos.","a":true},{"q":"El monomito de Campbell (1949) es un método folclórico tan comprobable como el conteo de funciones de Propp.","a":false},{"q":"Alan Dundes objetó que el monomito se ajusta después recortando lo que no encaja.","a":true},{"q":"Los quince golpes de Snyder (2005) se declaran a sí mismos como plantilla comercial.","a":true},{"q":"El paradigma de tres actos de Syd Field (1979) es un hallazgo científico sobre la narración humana.","a":false},{"q":"Reagan y colegas (2016) midieron 1,327 obras y hallaron seis formas emocionales recurrentes.","a":true},{"q":"El estudio de Reagan y colegas (2016) afirma que sus seis formas valen para toda la narración humana sin excepción.","a":false},{"q":"Ursula K. Le Guin (1986) propuso pensar la historia como una bolsa que se llena, no como una lanza que se lanza.","a":true},{"q":"El kishōtenketsu necesita siempre un antagonista con cara para funcionar.","a":false},{"q":"Jane Alison (2019) catalogó el meandro, la espiral y la red como patrones narrativos que no son un arco.","a":true},{"q":"Kurt Vonnegut nunca tuvo problemas para que aceptaran su idea sobre las formas de las historias.","a":false},{"q":"Cuando una estructura no se puede verificar, esta etapa enseña a dejarla pendiente en vez de inventar el dato que falta.","a":true}];
const evalMCBank=[{"q":"¿Qué exige la regla de oro de esta materia?","o":["a) Que la estructura sea la más antigua","b) Que la use un guionista famoso","c) Que se cite con autor, año y crítica","d) Que tenga tres actos exactos"],"a":2},{"q":"¿Qué son la peripecia y el reconocimiento (Aristóteles, Poética)?","o":["a) Dos actos del drama alemán","b) El vuelco hacia lo contrario y el paso de la ignorancia al saber","c) Los dos primeros golpes de Snyder","d) Dos funciones de Propp"],"a":1},{"q":"¿De qué año es la pirámide de Freytag, y para qué género la dibujó?","o":["a) 1863, drama alemán de cinco actos","b) 1949, mitología comparada","c) 1979, cine comercial","d) 2016, corpus digital"],"a":0},{"q":"¿Qué propone Todorov (1969) en «Grammaire du Décaméron»?","o":["a) Los quince golpes","b) El monomito","c) Equilibrio, ruptura y nuevo equilibrio","d) Las siete tramas básicas"],"a":2},{"q":"¿Qué objetó Alan Dundes al monomito de Campbell (1949)?","o":["a) Que no es método folclórico comprobable y se ajusta recortando lo que no encaja","b) Que tiene pocas etapas","c) Que Campbell nunca leyó mitos griegos","d) Que solo sirve para el teatro"],"a":0},{"q":"¿Qué es «El viaje del escritor» de Christopher Vogler?","o":["a) Un hallazgo de folclore","b) El monomito adaptado para el guion de cine comercial, declarado como manual","c) Una crítica al monomito","d) Una medición de 1,327 obras"],"a":1},{"q":"¿Qué venden Field (1979) y Snyder (2005), y cómo lo declaran?","o":["a) Ciencia sobre la narración humana, sin decirlo","b) Plantillas de industria para el guion de cine comercial, declaradas por ellos mismos","c) Clasificaciones de trama, sin declarar nada","d) Mediciones con corpus, sin límite"],"a":1},{"q":"¿Qué es «The Seven Basic Plots» de Christopher Booker (2004)?","o":["a) Una clasificación de tramas, criticada por lo moralizante y por elegir ejemplos a conveniencia","b) Una medición con corpus","c) Una plantilla de industria declarada","d) Una forma tradicional sin autor"],"a":0},{"q":"¿Qué le pasó a la tesis de Kurt Vonnegut sobre las formas de las historias?","o":["a) Ganó un premio","b) La Universidad de Chicago se la rechazó","c) Nunca la escribió","d) La publicó de inmediato en 1949"],"a":1},{"q":"¿Qué midieron Reagan, Mitchell, Kiley, Danforth y Dodds en 2016?","o":["a) 31 funciones en cien cuentos","b) Las ventas de guiones de Hollywood","c) El monomito en mil mitos","d) El tono emocional de 1,327 obras del Proyecto Gutenberg, hallando seis formas"],"a":3},{"q":"¿Cuál es el límite que el propio estudio de 2016 reconoce?","o":["a) Que midieron muy pocas obras","b) Que no usaron ningún método estadístico","c) Que las seis formas nunca se repiten","d) Que su corpus es casi todo occidental y en inglés"],"a":3},{"q":"¿Qué objeta Ursula K. Le Guin (1986) en «The Carrier Bag Theory of Fiction»?","o":["a) Que toda historia necesita más peripecia","b) Que el monomito mide bien","c) Que contar toda historia como un héroe, una lanza y un choque no es la única manera","d) Que Freytag tenía razón"],"a":2},{"q":"¿Qué cataloga Jane Alison en «Meander, Spiral, Explode» (2019)?","o":["a) Los quince golpes de Snyder","b) Las 31 funciones de Propp","c) El paradigma de tres actos","d) Patrones narrativos que no son un arco: el meandro, la espiral, la red"],"a":3},{"q":"¿Qué etiqueta le corresponde al kishōtenketsu?","o":["a) Forma tradicional, sin autor único","b) Medición con corpus","c) Plantilla comercial declarada","d) Hallazgo con réplica fallida"],"a":0},{"q":"¿Qué se hace cuando el autor o la fecha de una estructura no se pueden comprobar?","o":["a) Se le atribuye a Aristóteles para que suene serio","b) Se descarta sin explicar por qué","c) Se deja pendiente, a la vista, sin inventar el dato","d) Se cita igual, sin decir nada"],"a":2}];
