// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"s. IV a. C.","icon":"🏛️","label":"Aristóteles","text":"En la <strong>«Poética»</strong>, Aristóteles pide <strong>principio, medio y fin</strong>, y en el medio sitúa la <strong>peripecia</strong> (el vuelco hacia lo contrario de lo esperado) y el <strong>reconocimiento</strong> (el paso de la ignorancia al saber). <strong>Por qué importa aquí:</strong> es la descripción más vieja que se sigue citando, y la primera que esta etapa fecha y limita. Clásico fundacional, con su límite: describe la tragedia griega, no toda narración."},{"y":"1863","icon":"🔺","label":"Freytag","text":"Gustav Freytag publica <strong>«Die Technik des Dramas»</strong> y dibuja la acción de un drama como una <strong>pirámide</strong>: sube, llega arriba, cae. <strong>Por qué importa aquí:</strong> es el ejemplo más citado de una convención de época y de género (el drama alemán de cinco actos) confundida después con una ley universal."},{"y":"1949","icon":"🦸","label":"Campbell","text":"Joseph Campbell publica <strong>«El héroe de las mil caras»</strong> y propone el <strong>monomito</strong>: salida, iniciación y regreso, un solo viaje que sostiene late bajo los mitos de muchos pueblos. <strong>Por qué importa aquí:</strong> es la plantilla influyente con crítica seria más citada de la etapa; Alan Dundes le objetó que no es método folclórico comprobable."},{"y":"1969","icon":"🔁","label":"Todorov","text":"Tzvetan Todorov publica <strong>«Grammaire du Décaméron»</strong> y describe el esquema <strong>equilibrio, ruptura, nuevo equilibrio</strong>. <strong>Por qué importa aquí:</strong> es un clásico estructuralista, una gramática y no una medición, que la casa aplica y también sabe cuándo no aplicar (cuando una historia real no tiene ruptura)."},{"y":"1979","icon":"🎞️","label":"Field","text":"Syd Field publica <strong>«Screenplay»</strong> y fija el <strong>paradigma de tres actos</strong>, con puntos de giro en páginas concretas. <strong>Por qué importa aquí:</strong> es la plantilla de industria más citada sin su etiqueta; convención para el largometraje comercial, no ley de la narración."},{"y":"2005","icon":"✏️","label":"Vonnegut","text":"Kurt Vonnegut explica, en <strong>«A Man Without a Country»</strong>, la idea que había defendido toda su vida en charlas: las historias tienen formas que se pueden dibujar como una curva. <strong>Por qué importa aquí:</strong> nació de una tesis de maestría que la Universidad de Chicago le rechazó, y aun así la mostró siempre con honradez, sin jurar que fuera la única forma que existía."},{"y":"2016","icon":"📈","label":"Reagan y colegas","text":"Andrew J. Reagan, Lewis Mitchell, Dilan Kiley, Christopher M. Danforth y Peter Sheridan Dodds publican en <strong>EPJ Data Science</strong> la medición de <strong>1,327 obras</strong> del Proyecto Gutenberg, y hallan <strong>seis formas</strong> emocionales recurrentes. <strong>Por qué importa aquí:</strong> es lo más cerca de un dato duro que tiene esta etapa, y aun así escribe su propio límite: corpus casi todo occidental y en inglés."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: SAVE THE CAT PARA EL VIDEO DEL VIERNES ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(declaraYAdapta){sfx(declaraYAdapta?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(declaraYAdapta){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📐</span><span class="ms-text"><strong>Tomaste solo el gancho y el giro de en medio:</strong> el video se grabó en las cuatro horas previstas, con las dos páginas que había, y en los créditos quedó escrito «gancho y punto medio, inspirados en Snyder, 2005». Nadie tuvo que inventar los golpes que no cabían.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🏷️</span><span class="ms-text"><strong>La plantilla quedó declarada, no escondida:</strong> la próxima vez que alguien pregunte de dónde salió esa estructura, la respuesta está escrita, con su autor y su año, en vez de repetirse de memoria como si fuera ley.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📋</span><span class="ms-text"><strong>Forzaste los quince golpes en dos páginas:</strong> ocho de ellos quedaron en una sola línea sin desarrollar, el guion se sintió apretado, y el equipo perdió una hora tratando de que cupieran todos.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🎬</span><span class="ms-text"><strong>Tratar una plantilla comercial como una fórmula obligatoria</strong> dejó una sola salida, cumplirla entera, en vez de preguntarse qué parte de verdad servía a este formato. Una plantilla se declara y se adapta; no se obedece al pie de la letra solo porque venga de un libro.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = la pirámide, paradoja = el monomito y
// su crítica, utilidad = las plantillas de industria, ruina = las seis
// formas medidas.
const parteData={"esperado":{"nombre":"La pirámide","icon":"🔺","estructura":{"title":"Qué es","info":"• <strong>Gustav Freytag, «Die Technik des Dramas» (1863)</strong>: acción ascendente, clímax, acción descendente y desenlace, dibujados como una montaña de cinco tramos<br>• Nació para describir el drama alemán de cinco actos del siglo XIX, no el cuento, ni el video, ni el informe<br>• Es la imagen más citada del oficio, y también la más citada sin su año<br>• Antes de Freytag, Aristóteles ya había pedido un principio, un medio y un fin: la pirámide es una manera concreta y fechada de dibujar ese medio"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿de qué año es, y para qué género se dibujó?<br>• Se comprueba si lo que se está contando tiene de verdad un clímax único, o si esa exigencia le viene impuesta desde fuera<br>• Se compara con formas que no suben ni bajan (kishōtenketsu, la espiral de Alison) para ver si el material encaja mejor en otra<br>• Si se usa, se declara: «esto sigue la pirámide de Freytag (1863)», nunca «así son todas las historias»"},"enfermedades":{"title":"Dónde se cae","info":"• En dibujarla sin decir que es de 1863 y del drama alemán, como si fuera una ley de la física<br>• En forzar un clímax único donde el material real tiene varias subidas parejas, o ninguna<br>• En usarla para un formato que no tiene ni de lejos su duración (un video de siete minutos no es una obra de cinco actos)<br>• En repetirla de memoria sin haber leído nunca a Freytag"},"cuidados":{"title":"En esta casa","info":"• Se usa como boceto de trabajo, nunca como plantilla obligatoria<br>• Se declara siempre con su autor y su año, «Freytag, 1863», al lado<br>• Se prueba contra el material real antes de imponerla: si no hay clímax único, no se inventa uno<br>• Y se enseña junto a formas que no son una pirámide, para que quede claro que es una elección, no una ley"}},"paradoja":{"nombre":"El monomito","icon":"🦸","estructura":{"title":"Qué es","info":"• <strong>Joseph Campbell, «El héroe de las mil caras» (1949)</strong>: salida, iniciación y regreso, un solo viaje que, según Campbell, se repite en los mitos de muchos pueblos<br>• Christopher Vogler lo adaptó para el cine en «El viaje del escritor» (1992, ed. ampliada 2007), declarado como manual de guion, no como hallazgo<br>• Es, con diferencia, la estructura más vendida de todo el oficio<br>• Influido por la psicología de Carl Jung: Campbell buscaba arquetipos compartidos, no un método de conteo como el de Propp (1928, etapa 2)"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿este viaje se está usando como inspiración declarada, o como prueba de que existe un patrón universal?<br>• Se comprueba si el corpus de ejemplos es de verdad amplio, o si son los mismos mitos occidentales de siempre<br>• Se le pide, como a cualquier estructura, su crítica al lado: la de Alan Dundes<br>• Se distingue de Propp (1928): Propp contó funciones en cien cuentos de un género y dijo que valía para ese género; Campbell afirmó un patrón para todos los mitos del mundo"},"enfermedades":{"title":"Dónde se cae","info":"• En venderlo como «ciencia comprobada», que es justo lo que Dundes le objetó: no es método folclórico comparable al de Propp, es una lectura personal que se ajusta después recortando lo que no encaja<br>• En olvidar el sesgo masculino y occidental del corpus con el que Campbell trabajó<br>• En obligar a una historia real (una maestra, un patrocinador) a tener un «llamado a la aventura» que no tuvo<br>• En confundir la plantilla de Vogler (declarada, de industria) con un hallazgo de folclorista"},"cuidados":{"title":"En esta casa","info":"• Se usa el motor de deseo y obstáculo de la etapa 2 antes que forzar las diecisiete etapas del monomito<br>• Si se cita a Campbell, se cita con Dundes al lado, siempre<br>• Se declara el sesgo del corpus cuando se use como ejemplo<br>• Y se recuerda que Vogler mismo lo llamó una plantilla práctica de guion, no una ley del alma humana"}},"utilidad":{"nombre":"Las plantillas de industria","icon":"🎬","estructura":{"title":"Qué es","info":"• <strong>Syd Field, «Screenplay» (1979)</strong>: planteamiento, confrontación y resolución, con puntos de giro en páginas concretas<br>• <strong>Blake Snyder, «Save the Cat!» (2005)</strong>: quince golpes (beats), cada uno con su página aproximada<br>• Las dos nacieron para vender guiones de largometraje a estudios de Hollywood, y lo dicen en su propia contraportada<br>• Christopher Booker, «The Seven Basic Plots» (2004), es distinta: no es una plantilla de industria, es una clasificación de tramas, y se le reprocha lo moralizante y el escoger ejemplos a conveniencia"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿el propio autor la declara como fórmula comercial, o la vende como descubrimiento?<br>• Field y Snyder se declaran a sí mismos: son manuales de oficio para un mercado concreto<br>• Se comprueba si el formato que se tiene entre manos (un video de siete minutos, un informe de dos páginas) tiene siquiera el tamaño para las páginas que la plantilla pide<br>• Se usa la parte que sirve (el gancho, el punto medio) y se declara de dónde sale"},"enfermedades":{"title":"Dónde se cae","info":"• En aplicar el conteo exacto de páginas a un formato que no tiene páginas de guion de cine<br>• En presentar «los quince golpes» como si fueran ley de toda historia y no una fórmula de un libro de 2005<br>• En no distinguir una plantilla comercial (Field, Snyder) de una clasificación (Booker) o de un hallazgo medido (Reagan y colegas)<br>• En avergonzarse de declarar el préstamo, como si citar la fuente restara mérito al trabajo"},"cuidados":{"title":"En esta casa","info":"• Toda plantilla comercial que se use en la casa se declara con su autor, su año, y la palabra «plantilla»<br>• Se adapta la proporción, no el conteo literal de páginas, a formatos cortos<br>• Se prefiere, cuando alcanza, el motor propio de la casa (deseo, obstáculo, apuesta) antes que una fórmula ajena<br>• Y se recuerda que una plantilla que funciona para vender un guion no promete nada sobre si el proyecto merece el dinero"}},"ruina":{"nombre":"Las seis formas medidas","icon":"📈","estructura":{"title":"Qué es","info":"• <strong>Andrew J. Reagan, Lewis Mitchell, Dilan Kiley, Christopher M. Danforth y Peter Sheridan Dodds, «The emotional arcs of stories are dominated by six basic shapes», EPJ Data Science (2016)</strong><br>• Midieron el tono emocional, palabra por palabra, de 1,327 obras de ficción del Proyecto Gutenberg<br>• Con herramientas estadísticas de reducción de dimensiones, las curvas resultantes se agruparon en seis formas recurrentes<br>• Es, de toda esta etapa, lo más cerca de un dato duro: no una intuición de autor, una medición con metodología publicada"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿de qué corpus salió la medición, y en qué idioma estaban esas obras?<br>• Se comprueba que el propio estudio escriba su límite: el corpus del Proyecto Gutenberg es casi todo occidental y en inglés<br>• Se distingue de una plantilla comercial: aquí nadie vende un curso, se publicó un método y un dato<br>• Se pregunta también qué formas no puede ver un método que mide subida y bajada de tono (el giro del kishōtenketsu, la espiral de Alison)"},"enfermedades":{"title":"Dónde se cae","info":"• En citar «las seis formas» sin decir que vienen de 1,327 libros y de qué biblioteca<br>• En tratar el número seis como si fuera cerrado y definitivo para toda la narración humana, y no para ese corpus<br>• En olvidar que un método construido sobre una curva de tensión no puede encontrar una forma que no sea una curva<br>• En no distinguir esto (medición con metodología) de Campbell (lectura personal) o de Snyder (plantilla comercial)"},"cuidados":{"title":"En esta casa","info":"• Se cita como la medición más seria de la etapa, con su cifra (1,327) y su límite (corpus occidental) siempre al lado<br>• Se usa como techo de lo que hoy se sabe, no como techo de lo que existe<br>• Se enseña junto al careo de esta misma etapa, que discute exactamente este límite<br>• Y se guarda como ejemplo de cómo se cita bien: con autor, año, revista, tamaño del corpus y límite escrito"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== LECTURAS (normas 5, 5-quater y 5-quinquies) =====================
// Seis textos (Borges, Cervantes, Harari, la entrevista de la casa, la
// conversación Quintero-Gala y el careo) con tres baterías: comprensión (30,
// cinco por voz), completar (12) y análisis complejo (12, sin XP a propósito).
// El armado en pantalla lo hace js/lecturas.js leyendo estos bancos; aquí
// viven los bancos y la impresión. Las preguntas se contestan con los textos
// delante: son examen de lectura, no de memoria.
const lectComprensionBank=[{"t":"Borges","q":"¿Cuál era el propósito de Cornelio Aráuz como catalogador?","o":["a) Clasificar libros por autor","b) Traducir cuentos rusos","c) Escribir su propia novela","d) Encontrar la forma única de todas las historias"],"c":3},{"t":"Borges","q":"¿Por qué tachó Aráuz la ficha de la pirámide de Freytag?","o":["a) Porque no le gustaba el color de la tinta","b) Porque Freytag nunca existió","c) Porque descubrió que describía solo el drama alemán de cinco actos, no toda historia","d) Porque prefería el kishōtenketsu"],"c":2},{"t":"Borges","q":"¿Qué le prometió el monomito de Campbell (1949) a Aráuz?","o":["a) Un sueldo mejor","b) La forma única que llevaba buscando toda su vida","c) Un viaje a Estados Unidos","d) Un cargo de director"],"c":1},{"t":"Borges","q":"¿Qué frase de Dundes hizo que Aráuz se reconociera a sí mismo?","o":["a) «Recortándole lo que no encajaba»","b) «El monomito es falso»","c) «Campbell nunca viajó»","d) «Las funciones son 31»"],"c":0},{"t":"Borges","q":"¿Qué encontró Aráuz al final sobre las seis formas medidas en 2016?","o":["a) Que eran mil trescientas veintisiete formas distintas","b) Que Reagan las inventó sin medir nada","c) Que coincidían exactamente con el monomito","d) Que el corpus de 1,327 libros era casi todo occidental y en inglés"],"c":3},{"t":"Cervantes","q":"¿Qué contaba el bachiller que había dicho el canónigo sobre el teatro de su tiempo?","o":["a) Que era perfecto","b) Que había que prohibirlo","c) Que Aristóteles estaba equivocado","d) Que las comedias nuevas son un monstruo cosido sin el orden de las antiguas"],"c":3},{"t":"Cervantes","q":"Según el bachiller, ¿qué pide Aristóteles sobre la acción de una historia?","o":["a) Que dure tres horas","b) Que sea una y trabada, de modo que si se quita un pedazo se disloque el resto","c) Que tenga cinco actos exactos","d) Que no tenga personajes"],"c":1},{"t":"Cervantes","q":"¿Qué responde Onofre Bracamonte en defensa de las comedias nuevas?","o":["a) Que las unidades no dan de comer, y el público paga por lo que lo mueve","b) Que está de acuerdo con el canónigo","c) Que nunca ha sacado una compañía","d) Que prefiere el teatro griego"],"c":0},{"t":"Cervantes","q":"¿Qué comparación usa la ventera para explicar que un mismo esqueleto puede vestir ropa distinta?","o":["a) Una comida que cambia de sabor cada día","b) Un caballo que cambia de dueño","c) Un traje que se corta de nuevo cada generación, sobre el mismo cuerpo","d) Un camino que cambia de nombre"],"c":2},{"t":"Cervantes","q":"¿Con qué autor moderno cierra el capítulo su broma final, atribuyéndole ideas que ya había dicho el canónigo?","o":["a) Gustav Freytag","b) Syd Field","c) Joseph Campbell","d) Kurt Vonnegut"],"c":1},{"t":"Harari","q":"¿Qué descubrieron Milman Parry y Albert Lord sobre la poesía oral?","o":["a) Que se componía encajando fórmulas repetidas, como piezas de un molde","b) Que se memorizaba palabra por palabra","c) Que no existía antes de la escritura","d) Que solo servía para la Ilíada"],"c":0},{"t":"Harari","q":"¿Qué pide Aristóteles, según el ensayo, y cuál es su límite?","o":["a) Principio, medio y fin, con peripecia; describe la tragedia griega, no toda narración","b) Tres actos; describe solo el cine","c) Seis formas; describe solo obras occidentales","d) Quince golpes; describe solo el teatro"],"c":0},{"t":"Harari","q":"¿Qué le objetó Alan Dundes al monomito de Campbell, y qué otra crítica se le suma?","o":["a) Que Campbell nunca escribió el libro","b) Que el monomito mide demasiadas obras","c) Que no es método comprobable, y que su corpus tiene sesgo occidental y masculino","d) Que es idéntico a la pirámide de Freytag"],"c":2},{"t":"Harari","q":"¿Qué midieron Reagan y colegas en 2016, y qué límite reconoce el propio estudio?","o":["a) 31 funciones; sin ningún límite","b) Cien mitos; sin fecha","c) Quince golpes; límite de páginas","d) 1,327 obras del Proyecto Gutenberg, hallando seis formas; corpus casi todo occidental y en inglés"],"c":3},{"t":"Harari","q":"¿Qué proponen Le Guin (1986) y Alison (2019) frente al modelo de héroe, lanza y choque?","o":["a) Que ese modelo es el único válido","b) Que hay tradiciones que narran reuniendo, y patrones (meandro, espiral, red) que no son un arco","c) Que hay que eliminar toda estructura","d) Que solo sirve para el cine"],"c":1},{"t":"Entrevista","q":"¿A qué debe Campbell su idea de que el monomito es un patrón compartido por la especie?","o":["a) A los viajes de Marco Polo","b) A los arquetipos de Carl Jung","c) A las funciones de Propp","d) A la pirámide de Freytag"],"c":1},{"t":"Entrevista","q":"¿Qué le concede Campbell a la objeción de Alan Dundes?","o":["a) Nada, la rechaza por completo","b) Que Dundes nunca lo leyó","c) Que su método no es comprobable como el de un folclorista que cuenta funciones; leyó buscando sentido, no clasificando","d) Que el monomito es falso"],"c":2},{"t":"Entrevista","q":"¿Qué reconoce Campbell sobre el sesgo de su corpus?","o":["a) Que no tiene ningún sesgo","b) Que solo estudió mitos africanos","c) Que se apoyó sobre todo en mitología occidental y trató a las heroínas como variación del mismo viaje","d) Que nunca leyó mitos traducidos"],"c":2},{"t":"Entrevista","q":"¿Qué opina Campbell del uso que Christopher Vogler le dio a su idea?","o":["a) Que es un uso honesto mientras se declare como manual y no como ley","b) Que le parece un robo","c) Que no lo conoce","d) Que prefiere que nadie la use"],"c":0},{"t":"Entrevista","q":"¿Qué le pide Campbell a alguien que use hoy el viaje del héroe?","o":["a) Que lo use como linterna, y diga de quién es y de qué año","b) Que lo use como jaula, sin cuestionarlo","c) Que nunca lo mencione","d) Que lo combine con los quince golpes de Snyder"],"c":0},{"t":"Quintero y Gala","q":"Según Gala, ¿qué relación tiene un molde con quien escribe?","o":["a) Ninguna, hay que evitarlos siempre","b) Es siempre un robo","c) Solo sirve en el teatro griego","d) Ayuda como la horma a la bota: sirve mientras es de uno, aprieta cuando manda solo"],"c":3},{"t":"Quintero y Gala","q":"¿Qué hizo Gala en «¿Por qué corres, Ulises?» (1975) con el molde de la Odisea?","o":["a) Lo copió palabra por palabra","b) Usó el mismo esqueleto (el que vuelve) y cambió dónde puso el peso: qué pasa cuando ya no reconoce lo que fue a defender","c) Lo rechazó por completo","d) Escribió sobre Aquiles, no sobre Ulises"],"c":1},{"t":"Quintero y Gala","q":"Según Gala, ¿cuándo usar un molde antiguo es honesto y cuándo es un robo?","o":["a) Es honesto si se declara de dónde sale; es robo fingir que no hay molde y que todo brotó de uno mismo","b) Siempre es robo","c) Nunca es honesto","d) Depende del precio de la entrada"],"c":0},{"t":"Quintero y Gala","q":"¿Qué forma no occidental menciona Gala, cuyo tercer movimiento no es un choque?","o":["a) El paradigma de tres actos","b) La estructura china en cuatro tiempos (kishōtenketsu)","c) Los quince golpes","d) El monomito"],"c":1},{"t":"Quintero y Gala","q":"¿Qué le queda a Gala de haber estudiado Derecho, según él mismo?","o":["a) Nada, lo olvidó todo","b) La costumbre de preguntar quién dictó una regla y cuándo, antes de darla por buena","c) El deseo de ejercer como abogado","d) El gusto por las leyes sin fecha"],"c":1},{"t":"Debate","q":"¿Cuál es la pregunta en disputa del careo?","o":["a) Si Aristóteles tenía razón sobre la tragedia","b) Si Freytag copió a Campbell","c) Si las seis formas de 2016 descubrieron algo universal o solo describen el canon de Occidente","d) Si el kishōtenketsu es más antiguo que la pirámide"],"c":2},{"t":"Debate","q":"¿Qué hizo el equipo de Reagan, según la defensa, que nadie había hecho antes a esa escala?","o":["a) Proponer una intuición sin medir nada","b) Traducir el monomito","c) Medir la intuición: 1,327 libros, con curvas de tono agrupadas por herramientas estadísticas","d) Rechazar toda forma narrativa"],"c":2},{"t":"Debate","q":"Según la objeción, ¿qué le pasa a un método que mide la subida y bajada del tono emocional?","o":["a) Que mide perfectamente cualquier forma que exista","b) Que solo funciona en francés","c) Que fue inventado por Le Guin","d) Que no puede encontrar formas que no suban ni bajen, como el giro del kishōtenketsu"],"c":3},{"t":"Debate","q":"¿Qué concede la defensa en las réplicas cruzadas?","o":["a) Que el límite del corpus es real y sincero, y que ampliarlo es trabajo pendiente","b) Que el estudio está mal hecho","c) Que Le Guin tiene razón en todo","d) Que las seis formas no existen"],"c":0},{"t":"Debate","q":"¿Qué dato dice la moderación que acercaría la disputa?","o":["a) Releer a Aristóteles","b) Contar más cuentos rusos","c) Preguntarle a Vonnegut","d) Correr el mismo método, u otro, sobre un corpus grande de tradiciones no occidentales"],"c":3}];
const lectCompletarBank=[{"t":"Borges","q":"Aráuz tachó la ficha de Freytag y escribió que una pirámide no es una ___.","a":"ley"},{"t":"Borges","q":"Dundes dijo que el monomito se ajusta después recortando lo que no ___.","a":"encaja"},{"t":"Cervantes","q":"El bachiller dice que la acción, según Aristóteles, ha de ser una y ___.","a":"trabada"},{"t":"Cervantes","q":"La ventera dice que no se vale llamar al ___ un cuerpo distinto solo porque le cambiaron la cinta.","a":"vestido"},{"t":"Harari","q":"Parry y Lord mostraron que la poesía oral se componía con fórmulas, como piezas de un ___.","a":"molde"},{"t":"Harari","q":"El corpus de Reagan y colegas es casi todo occidental y en ___.","a":"inglés"},{"t":"Entrevista","q":"Campbell dice que su idea de los arquetipos se la debe al psiquiatra suizo Carl ___.","a":"Jung"},{"t":"Entrevista","q":"Campbell le pide a quien use el viaje del héroe que diga de quién es la ___ y de qué año.","a":"linterna"},{"t":"Quintero y Gala","q":"Gala dice que un molde ayuda igual que la horma ayuda a la ___.","a":"bota"},{"t":"Quintero y Gala","q":"Gala escribió «¿Por qué corres, ___?» en 1975.","a":"Ulises"},{"t":"Debate","q":"Le Guin propuso, en 1986, la teoría de la ___.","a":"bolsa"},{"t":"Debate","q":"El dato que acercaría la disputa es medir un corpus no ___.","a":"occidental"}];
const lectAnalisisBank=[{"t":"Borges","q":"Aráuz pasó diez años forzando historias dentro de las diecisiete etapas del monomito de Campbell. Explica qué hacía mal exactamente, usando la objeción de Dundes, y por qué la frase «recortándole lo que no encajaba» lo describe a él mismo.","guia":"Se valora que se explique con precisión la operación de Aráuz: no inventaba datos, pero sí ajustaba cada historia real, quitándole partes, hasta que cupiera en un molde de diecisiete etapas que él había decidido de antemano que debía cumplirse. Eso es exactamente lo que Dundes le objetó a Campbell: que el monomito no se comprueba, se impone, y que las excepciones se resuelven recortando el material y no revisando la teoría. Una respuesta buena señala el momento en que Aráuz reconoce la frase de Dundes como un espejo de su propio método, y por qué ese reconocimiento lo lleva a cerrar el cajón: entendió que estaba haciendo ciencia falsa con buena fe."},{"t":"Borges","q":"El cuento cierra con la frase de Aráuz sobre la forma que lleva fecha y la que no. Explica esa distinción apoyándote en el propio arco del cuento, desde Aristóteles hasta las seis formas de 2016.","guia":"Se valora que se recorra el arco completo: Aráuz prueba primero a Aristóteles (insuficiente), luego a Freytag (parroquial, solo el drama alemán de 1863), luego al monomito de Campbell (que se derrumba con la objeción de Dundes), y termina con la medición de 2016, que es la única de las cuatro que llega acompañada de su propio límite escrito. Una respuesta buena explica que la frase final no es un consuelo triste sino un hallazgo real: una forma sin fecha exige fe, como una superstición, y una forma con fecha se puede evaluar, discutir y hasta descartar, como una herramienta, que es justamente lo que le faltó a Aráuz durante treinta años de fichas."},{"t":"Cervantes","q":"El bachiller y Bracamonte no llegan a un acuerdo, pero la ventera resuelve la disputa con una imagen doméstica. Explica su argumento del vestido y el cuerpo, y por qué logra lo que los dos hombres no lograron.","guia":"Se valora que se explique la imagen con precisión: un traje se le puede cortar de nuevo a un cuerpo cada generación, con la tela que se lleve ese año, y sigue siendo el mismo cuerpo debajo; lo que no se vale es decir que el vestido es un cuerpo distinto solo porque le cambiaron la cinta. Una respuesta buena explica por qué esa imagen resuelve lo que el bachiller (defensor de las unidades) y Bracamonte (defensor de lo que el público paga) no lograban solos: traslada la discusión de si hay o no un esqueleto común a la pregunta de si la ropa nueva le sienta bien, que es una pregunta de oficio y no de doctrina, y que además, al venir de quien lleva veinte años sirviendo mesas y viendo compañías pasar, tiene la autoridad de la experiencia y no solo de la lectura."},{"t":"Cervantes","q":"El capítulo cierra con una broma anacrónica sobre un tal Syd Field. Explica qué relación establece esa broma entre el canónigo del siglo XVII y el paradigma de tres actos del siglo XX, y por qué el narrador la cuenta como rumor y no como hecho.","guia":"Se valora que se entienda la broma en su doble función: por un lado, conecta con humor la crítica del canónigo (que el teatro de su tiempo cosía escenas por lo que el público pagaba, sin el orden de los antiguos) con la idea de que siglos después alguien volvería a vender, como fórmula nueva, la misma pregunta sobre el orden de una historia; por otro lado, el narrador la marca como algo que «cuentan las malas lenguas», es decir, como leyenda de venta y no como hecho verificado, precisamente porque unir a Cervantes con un autor de 1979 de forma literal sería falso, y la regla de esta casa exige declarar la ficción cuando se usa. Una respuesta buena nota que ese cuidado es, en sí mismo, un ejemplo de la regla de oro de la etapa aplicada al propio texto que la enseña."},{"t":"Harari","q":"El ensayo abre con Milman Parry y Albert Lord y cierra con un informe sin fecha ni autor. Explica cómo se conecta el hallazgo sobre la poesía oral con la corrección final que propone el ensayo.","guia":"Se valora que se entienda el hilo completo: Parry y Lord mostraron que los cantores orales componían encajando fórmulas repetidas, un molde que sostenía la memoria de poemas de miles de versos sin necesidad de escritura; esa es la prueba más antigua de que los moldes narrativos cumplen una función real, no son un capricho académico. Una respuesta buena explica que el ensayo usa ese origen honesto de los moldes para, al final, denunciar su mal uso actual: un informe o una plantilla que se cita sin autor ni año pierde justamente la función que los moldes orales sí cumplían, que era ayudar a que algo se recordara y se transmitiera bien, y se convierte en una superstición que nadie puede revisar."},{"t":"Harari","q":"El ensayo distingue con cuidado el trabajo de Reagan y colegas (2016) del de Campbell (1949), y pone a Le Guin y Alison como una tercera vía. Explica las tres posturas y en qué se diferencian.","guia":"Se valora que se distingan las tres con precisión: Reagan y colegas midieron el tono emocional de 1,327 obras y agruparon las curvas con herramientas estadísticas, y su propio estudio declara el límite del corpus, así que es la postura de la medición seria y honesta sobre su alcance; Campbell leyó mitos buscando sentido y afirmó un patrón universal sin comprobarlo con un método repetible, por lo que es la postura de la lectura personal vendida, a veces, como si fuera más que eso; y Le Guin (1986) junto con Alison (2019) no miden ni proponen un patrón único, sino que muestran que el propio modelo de arco deja fuera formas reales que no suben ni bajan. Una respuesta buena nota que las tres reciben en el ensayo el mismo trato: se citan con su autor, su año y su límite."},{"t":"Entrevista","q":"Campbell concede en la entrevista que su método no es como el de Propp. Explica esa concesión con tus propias palabras y di por qué Soler Serrano insiste en sacarla.","guia":"Se valora que se entienda la concesión con exactitud: Campbell reconoce que Propp contó, tomó cien cuentos de un género y anotó qué función cumplía cada parte, algo que se puede repetir y discutir con números delante, mientras que él leyó buscando sentido, un trabajo distinto y no necesariamente peor, pero que no debería llevar la ropa de una ciencia que no es. Una respuesta buena explica que Soler Serrano insiste porque esa es la pieza central de la lectura: sin esa concesión, la entrevista dejaría al monomito sin su crítica, y esta casa no permite que ninguna estructura se quede sin la suya, ni siquiera en boca de su propio autor imaginado."},{"t":"Entrevista","q":"Campbell reconoce también el sesgo occidental y masculino de su corpus. Explica qué significa esa concesión y por qué es distinta de la concesión sobre el método.","guia":"Se valora que se distingan las dos concesiones: la primera, sobre el método, dice que la manera de trabajar de Campbell no es comprobable como la de un folclorista que cuenta funciones; la segunda, sobre el corpus, dice que además los mitos que leyó venían sobre todo de la tradición europea, traducidos y disponibles en su época, y que trató a las heroínas como una variación del viaje masculino en vez de preguntarse si merecían su propio dibujo. Una respuesta buena explica que un método puede ser honesto en su propósito y aun así tener un corpus parcial, y que reconocer las dos cosas por separado es más riguroso que decir, en general, «el libro tiene problemas»."},{"t":"Quintero y Gala","q":"Gala explica que reescribir la Odisea en «¿Por qué corres, Ulises?» no es traicionar a Homero. Explica su argumento y compara su postura con la advertencia final que le da a Quintero sobre fechar los moldes.","guia":"Se valora que se entienda el argumento de Gala: usar un molde antiguo no es traición si se declara desde el título que se está usando, como con Ulises, cuyo regreso todo el mundo reconoce, y cambiar el peso de la pregunta (no si vuelve, sino qué encuentra al volver) es la sangre propia que se le pone dentro; lo que sí sería traición, dice Gala, es fingir que no hay ningún molde detrás. Una respuesta buena conecta esto con su advertencia final a Quintero: una forma que oculta su fecha se hace pasar por más vieja y más sagrada de lo que es, así que declarar el préstamo, como hizo con Ulises, es la misma honradez, aplicada al propio oficio de escribir, que esta etapa pide para cualquier estructura citada."},{"t":"Quintero y Gala","q":"Gala menciona una tradición no occidental, la de cuatro tiempos con un giro que no es choque, casi de pasada, con humildad. Explica qué función cumple esa mención dentro de la conversación.","guia":"Se valora que se entienda por qué Gala la trae con cautela, diciendo «he leído que», y no como una autoridad que domina: la usa para contrastar su propia tradición, la griega, la del choque y la cólera, con una calma que le parece una lección, sin apropiarse de un conocimiento que no es el suyo. Una respuesta buena señala que esa humildad es coherente con el tema entero de la conversación, que las formas tienen dueño y fecha, y que hablar de una tradición ajena exige el mismo cuidado que hablar de la propia: decir de dónde se aprendió, y no presentarlo como un descubrimiento propio."},{"t":"Debate","q":"La defensa admite que el corpus de 2016 es limitado, pero dice que eso no invalida la medición. Explica ese argumento y por qué no es lo mismo que decir que el hallazgo es falso.","guia":"Se valora que se distinga con claridad entre limitar el alcance de un hallazgo y invalidarlo: la defensa concede que 1,327 obras, casi todas occidentales y en inglés, no representan a toda la narración humana, pero sostiene que dentro de ese corpus la medición es real, comprobable y más modesta que el monomito de Campbell, que nunca midió nada y aun así afirmó valer para todos los mitos del mundo. Una respuesta buena explica que reconocer un límite es distinto de estar equivocado: seis formas encontradas en 1,327 libros occidentales siguen siendo un hecho sobre esos 1,327 libros, y el problema solo aparece si alguien las presenta como un hecho sobre la humanidad entera."},{"t":"Debate","q":"La objeción sostiene que el método de 2016 es ciego a ciertas formas por diseño, no solo por el corpus que usó. Explica esa distinción con el ejemplo del kishōtenketsu.","guia":"Se valora que se entienda el argumento más fino de la objeción: no basta con ampliar el corpus si el instrumento de medir sigue trazando el tono emocional como una curva que sube y baja, porque ese instrumento presupone, antes de medir nada, que toda historia se deja describir como tensión creciente y decreciente. El kishōtenketsu resuelve su tercer movimiento con un giro, un cambio de perspectiva, no con un choque que suba la tensión, así que un método que solo sabe buscar picos y valles no encontraría esa forma aunque la tuviera delante, en cualquier idioma. Una respuesta buena distingue este problema de diseño del problema de corpus, y explica por qué la moderación pide, al final, no solo más libros sino, si es posible, otro instrumento."}];
